<?php
require_once __DIR__.'/../includes/functions.php';admin_only();
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$id=(int)($_POST['id']??0);$status=$_POST['status']??'Pending';$allowed=['Pending','Processing','Shipped','Delivered','Cancelled'];if(in_array($status,$allowed,true)){$st=$pdo->prepare("UPDATE orders SET status=? WHERE id=?");$st->execute([$status,$id]);}header('Location: manage-orders.php');exit;}
$orders=$pdo->query("SELECT o.*,c.name customer_name,c.email FROM orders o JOIN customers c ON c.id=o.customer_id ORDER BY o.created_at DESC")->fetchAll();$pageTitle='Manage orders';include __DIR__.'/../includes/admin-header.php';?>
<section class="admin-main"><div class="admin-heading"><h1>Customer orders</h1></div><div class="admin-panel table-wrap"><table><thead><tr><th>Order</th><th>Customer</th><th>Phone</th><th>Total</th><th>Status</th><th>Update</th></tr></thead><tbody><?php foreach($orders as $o): ?><tr><td>#<?= (int)$o['id'] ?><small><?= e($o['created_at']) ?></small></td><td><?= e($o['customer_name']) ?><small><?= e($o['email']) ?></small></td><td><?= e($o['phone']) ?></td><td><?= money((float)$o['total_amount']) ?></td><td><?= e($o['status']) ?></td><td><form method="post" class="inline-form"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><input type="hidden" name="id" value="<?= (int)$o['id'] ?>"><select name="status"><?php foreach(['Pending','Processing','Shipped','Delivered','Cancelled'] as $s): ?><option <?= $s===$o['status']?'selected':'' ?>><?= $s ?></option><?php endforeach; ?></select><button class="button button-small">Save</button></form></td></tr><?php endforeach; ?></tbody></table></div></section><?php include __DIR__.'/../includes/admin-footer.php';?>
